"use strict";(self.webpackChunk_servicenow_sdk_docs=self.webpackChunk_servicenow_sdk_docs||[]).push([["863886"],{752230(e){e.exports=JSON.parse('{"tag":{"label":"view","permalink":"/sdk/4.13.6/tags/view","allTagsPath":"/sdk/4.13.6/tags","count":4,"items":[{"id":"guides/database-view-guide","title":"Database Views","description":"Guide for creating ServiceNow Database Views (sysdbview) using the Fluent API. A Database View is a read-only virtual table that SQL-joins two or more real tables into a single reportable pseudo-table, exposing selected columns from each joined table under a per-table variable prefix. Use it when you need to report across, or build lists/queries on top of, data that already lives in other tables \u2014 a Database View stores no data of its own.","permalink":"/sdk/4.13.6/guides/database-view-guide"},{"id":"api/form-api","title":"Form","description":"Creates a form definition (sysuiform) for a ServiceNow table with sections and layout blocks.","permalink":"/sdk/4.13.6/api/form-api"},{"id":"api/list-api","title":"List","description":"Creates a list layout for a table (sysuilist) with column definitions (sysuilist_element).","permalink":"/sdk/4.13.6/api/list-api"},{"id":"guides/view-guide","title":"Views","description":"Guide for creating ServiceNow UI Views using the Record API. Views define custom layout variants for forms and lists, controlling which fields/columns are shown and who can access the layout.","permalink":"/sdk/4.13.6/guides/view-guide"}],"unlisted":false}}')}}]);